import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import BuildCard from './BuildCard';
import { openBuildEditor } from './openers';
import useStyles from '../styles';
import { t, money } from '../util';

/** Profile → Garage: the member's builds (their drafts too, on their own profile). */
export default class UserGaragePage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
    this.builds = null;
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (this.shownFor === user.id()) return;
    this.shownFor = user.id();
    app.store.find('garage-builds', {
      filter: {
        user: user.id()
      },
      sort: '-lastActivityAt',
      page: {
        limit: 48,
        total: 0
      }
    }).then(builds => {
      this.builds = builds;
      m.redraw();
    });
  }
  content() {
    if (!this.builds) return m(LoadingIndicator, {
      display: "block"
    });
    const own = app.session.user === this.user;
    const canAdd = own && app.forum.attribute('garageCanCreate');
    const published = this.builds.filter(b => b.published());
    const sum = fn => published.reduce((n, b) => n + (Number(fn(b)) || 0), 0);
    return m("div", {
      className: "GarageUserPage"
    }, this.builds.length ? m("div", {
      className: "GarageUserPage-header"
    }, m("ul", {
      className: "GarageUserPage-stats"
    }, m("li", null, m("strong", null, published.length), " ", t('profile.builds', {
      count: published.length
    })), m("li", null, m("strong", null, sum(b => b.entryCount())), " ", t('profile.updates', {
      count: sum(b => b.entryCount())
    })), m("li", null, m("strong", null, sum(b => b.likeCount())), " ", t('profile.likes', {
      count: sum(b => b.likeCount())
    })), sum(b => b.spent()) ? m("li", null, m("strong", null, money(sum(b => b.spent()))), " ", t('profile.spent')) : null), canAdd ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => openBuildEditor({})
    }, t('page.add')) : null) : null, this.builds.length ? m("div", {
      className: "GarageGrid GarageGrid--profile"
    }, this.builds.map(build => m(BuildCard, {
      build: build
    }))) : m("div", {
      className: "GarageEmpty"
    }, m(Icon, {
      name: "fas fa-warehouse"
    }), m("p", null, own ? t('profile.empty_own') : t('profile.empty', {
      username: this.user.displayName()
    })), canAdd ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => openBuildEditor({})
    }, t('page.add')) : null));
  }
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/UserGaragePage', UserGaragePage);